            id = id.from(_N, "UpdateUserInput", "Surname"),
            type = "string",
            name = "Surname",
            target_id = prelude.String.id,
        }),
        OtherAttributes = schema.new({
            id = id.from(_N, "UpdateUserInput", "OtherAttributes"),
            type = "map",
            name = "OtherAttributes",
            target_id = prelude.Document.id,
            map_key = prelude.String,
            map_value = M.AttributeValue,
        }),
        UpdateType = schema.new({
            id = id.from(_N, "UpdateUserInput", "UpdateType"),
            type = "string",
            name = "UpdateType",
            target_id = prelude.String.id,
        }),
        ClientToken = schema.new({
            id = id.from(_N, "UpdateUserInput", "ClientToken"),
            type = "string",
            name = "ClientToken",
            target_id = prelude.String.id,
            traits = {
                [traits.IDEMPOTENCY_TOKEN] = {},
            },
        }),
    },
})

M.UpdateUserOutput = schema.new({
    id = id.from(_N, "UpdateUserResult"),
    type = "structure",
})

-- Fix forward references for recursive schemas
for _, s in pairs(M) do
    if type(s) == "table" and (s.type == "structure" or s.type == "union") then
        local members = rawget(s, "_members")
        if members then
            for _, ms in pairs(members) do
                if (ms.type == "structure" or ms.type == "union") and not rawget(ms, "_target") and ms.target_id then
                    rawset(ms, "_target", M[ms.target_id.name])
                end
            end
        end
    end
end

return M
